function MiniCalendar({ appointments }) {
  const MESES = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
  const today = new Date(2026, 7, 11); // demo: 11 de agosto 2026
  const [cursor, setCursor] = useState(new Date(2026, 7, 1));
  const year = cursor.getFullYear(), month = cursor.getMonth();
  const firstDow = (new Date(year, month, 1).getDay() + 6) % 7; // lunes=0
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const apptDays = new Set(appointments.filter(a => {
    const d = new Date(a.fecha); return d.getFullYear() === year && d.getMonth() === month;
  }).map(a => new Date(a.fecha).getDate()));
  const cells = [...Array(firstDow).fill(null), ...Array.from({ length: daysInMonth }, (_, i) => i + 1)];
  const changeMonth = (delta) => setCursor(new Date(year, month + delta, 1));
  return (
    <div className="rounded-2xl p-5 h-full" style={{ background: A.panel, border: `1px solid ${A.line}` }}>
      <div className="flex items-center justify-between mb-4">
        <p className="text-sm font-semibold" style={{ color: A.ink }}>{MESES[month]} {year}</p>
        <div className="flex gap-1">
          <button onClick={() => changeMonth(-1)} className="w-6 h-6 rounded flex items-center justify-center" style={{ background: A.bg }}><ChevronLeft size={13} /></button>
          <button onClick={() => changeMonth(1)} className="w-6 h-6 rounded flex items-center justify-center" style={{ background: A.bg }}><ChevronRight size={13} /></button>
        </div>
      </div>
      <div className="grid grid-cols-7 gap-y-1.5 text-center">
        {["L","M","M","J","V","S","D"].map((d, i) => (
          <span key={i} className="text-[10px]" style={{ color: A.sub }}>{d}</span>
        ))}
        {cells.map((d, i) => {
          const isToday = d && year === today.getFullYear() && month === today.getMonth() && d === today.getDate();
          const hasAppt = d && apptDays.has(d);
          return (
            <div key={i} className="aspect-square flex items-center justify-center relative">
              {d && (
                <span
                  className="w-7 h-7 rounded-full flex items-center justify-center text-xs"
                  style={{ background: isToday ? A.accent : "transparent", color: isToday ? "#fff" : A.ink, fontWeight: isToday ? 700 : 400 }}
                >
                  {d}
                  {hasAppt && !isToday && <span className="absolute bottom-0.5 w-1 h-1 rounded-full" style={{ background: A.accent }} />}
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function StatusBadge({ status }) {
  const s = STATUS_STYLES[status] || { bg: "#EEE", fg: A.sub };
  return <span className="text-xs px-2.5 py-1 rounded-full font-medium" style={{ background: s.bg, color: s.fg }}>{status}</span>;
}

function ProspectosView({ leads, setLeads, appointments, setAppointments, role, onCreateQuote }) {
  const [openId, setOpenId] = useState(null);
  const open = leads.find((l) => l.id === openId);
  const [query, setQuery] = useState("");

  const filtered = leads.filter((l) => (l.name + l.product + l.finish).toLowerCase().includes(query.toLowerCase()));

  const updateLead = (id, patch) => setLeads((prev) => prev.map((l) => (l.id === id ? { ...l, ...patch } : l)));
  const deleteLead = (id) => { setLeads((prev) => prev.filter((l) => l.id !== id)); setOpenId(null); };

  return (
    <div>
      <div className="flex items-center gap-3 mb-5">
        <div className="flex items-center gap-2 px-3 py-2 rounded-lg flex-1 max-w-sm" style={{ background: A.panel, border: `1px solid ${A.line}` }}>
          <Search size={14} style={{ color: A.sub }} />
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar prospecto..." className="text-sm outline-none w-full" style={{ background: "transparent" }} />
        </div>
      </div>

      <div className="rounded-2xl overflow-hidden" style={{ background: A.panel, border: `1px solid ${A.line}` }}>
        <table className="w-full text-sm">
          <thead>
            <tr style={{ borderBottom: `1px solid ${A.line}` }}>
              {["Nombre", "WhatsApp", "Producto", "Espacio", "Estado", "Fecha", ""].map((h) => (
                <th key={h} className="text-left px-4 py-3 text-xs font-medium" style={{ color: A.sub }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map((l) => (
              <tr key={l.id} onClick={() => setOpenId(l.id)} className="cursor-pointer" style={{ borderBottom: `1px solid ${A.line}` }}>
                <td className="px-4 py-3 font-medium" style={{ color: A.ink }}>{l.name}</td>
                <td className="px-4 py-3" style={{ color: A.sub }}>{l.whatsapp}</td>
                <td className="px-4 py-3" style={{ color: A.sub }}>{l.product}</td>
                <td className="px-4 py-3" style={{ color: A.sub }}>{l.space}</td>
                <td className="px-4 py-3"><StatusBadge status={l.status} /></td>
                <td className="px-4 py-3" style={{ color: A.sub }}>{l.date}</td>
                <td className="px-4 py-3"><ChevronRight size={15} style={{ color: A.sub }} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {open && (
        <ProspectoDrawer
          lead={open}
          role={role}
          onClose={() => setOpenId(null)}
          onUpdate={(patch) => updateLead(open.id, patch)}
          onDelete={() => deleteLead(open.id)}
          onCreateAppointment={(appt) => setAppointments((prev) => [appt, ...prev])}
          onCreateQuote={onCreateQuote}
        />
      )}
    </div>
  );
}

function ProspectoDrawer({ lead, role, onClose, onUpdate, onDelete, onCreateAppointment, onCreateQuote }) {
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [notes, setNotes] = useState([]);
  const [note, setNote] = useState("");
  const addNote = () => { if (!note.trim()) return; setNotes((n) => [{ text: note, date: new Date().toISOString().slice(0, 10) }, ...n]); setNote(""); };
  const createAppt = () => {
    onCreateAppointment({ id: "A-" + Math.floor(Math.random() * 900 + 100), cliente: lead.name, fecha: "Por definir", hora: "—", tipo: "Visita técnica", lugar: "—", estado: "Pendiente" });
  };
  return (
    <div className="fixed inset-0 z-50 flex justify-end" style={{ background: "rgba(34,29,23,0.35)" }} onClick={onClose}>
      <div className="w-full max-w-md h-full overflow-y-auto p-6" style={{ background: A.panel }} onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-6">
          <p className="text-xs" style={{ color: A.sub }}>{lead.id} · {lead.origen}</p>
          <button onClick={onClose}><X size={18} style={{ color: A.sub }} /></button>
        </div>
        <h3 className="text-xl font-semibold mb-1" style={{ color: A.ink }}>{lead.name}</h3>
        <p className="text-sm mb-5" style={{ color: A.sub }}>{lead.whatsapp}</p>

        <div className="grid grid-cols-2 gap-4 mb-6 text-sm">
          <div><p className="text-xs mb-1" style={{ color: A.sub }}>Producto</p><p style={{ color: A.ink }}>{lead.product}</p></div>
          <div><p className="text-xs mb-1" style={{ color: A.sub }}>Acabado</p><p style={{ color: A.ink }}>{lead.finish}</p></div>
          <div><p className="text-xs mb-1" style={{ color: A.sub }}>Espacio</p><p style={{ color: A.ink }}>{lead.space}</p></div>
          <div><p className="text-xs mb-1" style={{ color: A.sub }}>Medidas</p><p style={{ color: A.ink }}>{lead.medidas}</p></div>
        </div>

        <label className="block mb-6">
          <span className="text-xs mb-1.5 block" style={{ color: A.sub }}>Estado</span>
          <select value={lead.status} onChange={(e) => onUpdate({ status: e.target.value })} className="w-full text-sm rounded-lg px-3 py-2.5" style={{ border: `1px solid ${A.line}` }}>
            {Object.keys(STATUS_STYLES).map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        </label>

        <div className="flex gap-2 mb-6 flex-wrap">
          <a href={buildWaLink({ product: lead.product, finish: lead.finish, space: lead.space, name: lead.name })} target="_blank" rel="noreferrer" className="flex items-center gap-2 text-xs px-3.5 py-2.5 rounded-full font-semibold" style={{ background: A.accent, color: "#fff" }}>
            <Phone size={13} /> WhatsApp
          </a>
          <button onClick={createAppt} className="flex items-center gap-2 text-xs px-3.5 py-2.5 rounded-full font-semibold" style={{ border: `1px solid ${A.line}`, color: A.ink }}>
            <CalendarDays size={13} /> Crear cita
          </button>
          <button onClick={() => onCreateQuote(lead)} className="flex items-center gap-2 text-xs px-3.5 py-2.5 rounded-full font-semibold" style={{ background: A.ink, color: "#fff" }}>
            <FileText size={13} /> Generar cotización
          </button>
          {role === "ADMIN" && (
            <button onClick={() => setConfirmDelete(true)} className="flex items-center gap-2 text-xs px-3.5 py-2.5 rounded-full font-semibold" style={{ color: A.red }}>
              <Trash2 size={13} /> Eliminar
            </button>
          )}
        </div>

        <p className="text-xs font-semibold mb-2 flex items-center gap-1.5" style={{ color: A.ink }}><StickyNote size={13} /> Notas</p>
        <div className="flex gap-2 mb-3">
          <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="Agregar nota..." className="flex-1 text-sm rounded-lg px-3 py-2" style={{ border: `1px solid ${A.line}` }} />
          <button onClick={addNote} className="px-3 rounded-lg" style={{ background: A.bg }}><Plus size={15} /></button>
        </div>
        <div className="flex flex-col gap-2">
          {notes.map((n, i) => (
            <div key={i} className="text-xs p-3 rounded-lg" style={{ background: A.bg, color: A.ink }}>
              <p>{n.text}</p>
              <p className="mt-1" style={{ color: A.sub }}>{n.date}</p>
            </div>
          ))}
        </div>
      </div>
      {confirmDelete && (
        <ConfirmDialog
          title="¿Eliminar este prospecto?"
          message={`Se eliminará "${lead.name}" y sus notas. Esta acción no se puede deshacer.`}
          onConfirm={onDelete}
          onCancel={() => setConfirmDelete(false)}
        />
      )}
    </div>
  );
}

