function ProductoDrawer({ product, isNew, onClose, onDelete }) {
  const { setProducts, finishes, setFinishes } = useProductData();
  const [confirmDeleteProduct, setConfirmDeleteProduct] = useState(false);
  const [confirmFinishId, setConfirmFinishId] = useState(null);
  const blank = { id: "", code: "", name: "", short: "", description: "", catalogGroup: "revestimientos", featured: false, simple: false };
  const [form, setForm] = useState(product ? { ...product } : blank);
  const [addingFinish, setAddingFinish] = useState(false);
  const productFinishes = product ? finishes.filter((f) => f.productId === product.id) : [];

  const setField = (k) => (e) => {
    const v = e.target.type === "checkbox" ? e.target.checked : e.target.value;
    setForm((f) => ({ ...f, [k]: v }));
  };

  const save = () => {
    if (isNew) {
      const id = (form.name || "producto").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") + "-" + Math.floor(Math.random() * 900 + 100);
      setProducts((prev) => [...prev, { ...form, id }]);
    } else {
      setProducts((prev) => prev.map((p) => (p.id === product.id ? { ...form } : p)));
    }
    onClose();
  };

  const addFinish = (finishForm) => {
    const id = product.id + "-" + Math.floor(Math.random() * 9000 + 1000);
    const index = `${(product.code || "AC")}-${String(productFinishes.length + 1).padStart(2, "0")}`;
    setFinishes((prev) => [...prev, buildFinishFromForm({ ...finishForm, id, productId: product.id, index })]);
    setAddingFinish(false);
  };
  const deleteFinish = (fid) => setFinishes((prev) => prev.filter((f) => f.id !== fid));

  return (
    <div className="fixed inset-0 z-50 flex justify-end" style={{ background: "rgba(34,29,23,0.35)" }} onClick={onClose}>
      <div className="w-full max-w-lg h-full overflow-y-auto p-6" style={{ background: A.panel }} onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-6">
          <p className="text-sm font-semibold" style={{ color: A.ink }}>{isNew ? "Nuevo producto" : product.name}</p>
          <button onClick={onClose}><X size={18} style={{ color: A.sub }} /></button>
        </div>

        <div className="grid grid-cols-2 gap-3 mb-4">
          <label className="block"><span className="text-xs mb-1 block" style={{ color: A.sub }}>Nombre</span><input value={form.name} onChange={setField("name")} className="ai" /></label>
          <label className="block"><span className="text-xs mb-1 block" style={{ color: A.sub }}>Código</span><input value={form.code} onChange={setField("code")} className="ai" placeholder="ej. WPC" /></label>
        </div>
        <label className="block mb-4"><span className="text-xs mb-1 block" style={{ color: A.sub }}>Descripción corta (tarjeta)</span><input value={form.short} onChange={setField("short")} className="ai" /></label>
        <label className="block mb-4"><span className="text-xs mb-1 block" style={{ color: A.sub }}>Descripción larga</span><textarea value={form.description} onChange={setField("description")} rows={3} className="ai" /></label>

        <div className="grid grid-cols-2 gap-3 mb-4">
          <label className="block">
            <span className="text-xs mb-1 block" style={{ color: A.sub }}>Categoría</span>
            <select value={form.catalogGroup} onChange={setField("catalogGroup")} className="ai">
              <option value="revestimientos">Revestimientos</option>
              <option value="exterior">Persianas y Exterior</option>
            </select>
          </label>
          <label className="block">
            <span className="text-xs mb-1 block" style={{ color: A.sub }}>Tipo</span>
            <select value={form.simple ? "simple" : "acabados"} onChange={(e) => setForm((f) => ({ ...f, simple: e.target.value === "simple" }))} className="ai">
              <option value="acabados">Con selector de acabados</option>
              <option value="simple">Servicio simple (sin acabados)</option>
            </select>
          </label>
        </div>
        <label className="flex items-center gap-2 mb-6 text-sm" style={{ color: A.ink }}>
          <input type="checkbox" checked={!!form.featured} onChange={setField("featured")} /> Mostrar en "Lo más solicitado"
        </label>

        <div className="flex gap-2 mb-8">
          <button onClick={save} className="flex items-center gap-2 text-xs px-4 py-2.5 rounded-full font-semibold" style={{ background: A.ink, color: "#fff" }}>
            <Check size={13} /> Guardar
          </button>
          {!isNew && (
            <button onClick={() => setConfirmDeleteProduct(true)} className="flex items-center gap-2 text-xs px-4 py-2.5 rounded-full font-semibold" style={{ color: A.red }}>
              <Trash2 size={13} /> Eliminar producto
            </button>
          )}
        </div>

        {!isNew && !form.simple && (
          <>
            <div className="flex items-center justify-between mb-3" style={{ borderTop: `1px solid ${A.line}`, paddingTop: 20 }}>
              <p className="text-xs font-semibold" style={{ color: A.ink }}>Acabados ({productFinishes.length})</p>
              <button onClick={() => setAddingFinish(true)} className="text-xs flex items-center gap-1.5" style={{ color: A.accent }}><Plus size={13} /> Agregar acabado</button>
            </div>
            <div className="flex flex-col gap-2">
              {productFinishes.map((f) => (
                <div key={f.id} className="flex items-center gap-3 p-2.5 rounded-lg" style={{ background: A.bg }}>
                  <div className="w-9 h-9 rounded-md shrink-0" style={textureStyle(f)} />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium truncate" style={{ color: A.ink }}>{f.name}</p>
                    <p className="text-[11px]" style={{ color: A.sub }}>{f.index}</p>
                  </div>
                  <button onClick={() => setConfirmFinishId(f.id)}><Trash2 size={13} style={{ color: A.sub }} /></button>
                </div>
              ))}
              {productFinishes.length === 0 && <p className="text-xs" style={{ color: A.sub }}>Sin acabados todavía.</p>}
            </div>
            {addingFinish && <AcabadoForm onCancel={() => setAddingFinish(false)} onSave={addFinish} />}
          </>
        )}
        <style>{`.ai { width:100%; border:1px solid ${A.line}; border-radius:8px; padding:8px 10px; font-size:13px; color:${A.ink}; background:${A.bg}; }`}</style>
      </div>
      {confirmDeleteProduct && (
        <ConfirmDialog
          title="¿Eliminar este producto?"
          message={`Se eliminará "${product?.name}" y todos sus acabados del catálogo público.`}
          onConfirm={onDelete}
          onCancel={() => setConfirmDeleteProduct(false)}
        />
      )}
      {confirmFinishId && (
        <ConfirmDialog
          title="¿Eliminar este acabado?"
          message="Desaparecerá del selector de acabados en el sitio público."
          onConfirm={() => { deleteFinish(confirmFinishId); setConfirmFinishId(null); }}
          onCancel={() => setConfirmFinishId(null)}
        />
      )}
    </div>
  );
}

function AcabadoForm({ onCancel, onSave }) {
  const [f, setF] = useState({ name: "", desc: "", base: "#8A6246", style: "madera" });
  return (
    <div className="mt-3 p-3 rounded-lg flex flex-col gap-2.5" style={{ border: `1px dashed ${A.line}` }}>
      <input value={f.name} onChange={(e) => setF((s) => ({ ...s, name: e.target.value }))} placeholder="Nombre del acabado" className="ai" />
      <input value={f.desc} onChange={(e) => setF((s) => ({ ...s, desc: e.target.value }))} placeholder="Descripción corta" className="ai" />
      <div className="flex items-center gap-3">
        <label className="flex items-center gap-2 text-xs" style={{ color: A.sub }}>
          Color base <input type="color" value={f.base} onChange={(e) => setF((s) => ({ ...s, base: e.target.value }))} />
        </label>
        <select value={f.style} onChange={(e) => setF((s) => ({ ...s, style: e.target.value }))} className="ai" style={{ flex: 1 }}>
          <option value="madera">Madera</option>
          <option value="marmol">Mármol</option>
          <option value="decorativo">Decorativo</option>
          <option value="ondulado">Ondulado</option>
        </select>
      </div>
      <div className="flex gap-2">
        <button onClick={() => f.name && onSave(f)} className="text-xs px-3.5 py-2 rounded-full font-semibold" style={{ background: A.ink, color: "#fff" }}>Agregar</button>
        <button onClick={onCancel} className="text-xs px-3.5 py-2 rounded-full" style={{ color: A.sub }}>Cancelar</button>
      </div>
    </div>
  );
}

const PROJECT_STAGES = ["Cotización", "Agendado", "En instalación", "Completado"];

function ProyectosView() {
  const [projects, setProjects] = useState(DEMO_DATA.projects);
  const [adding, setAdding] = useState(false);
  const [confirmId, setConfirmId] = useState(null);
  const confirmProject = projects.find((p) => p.id === confirmId);

  const moveProject = (id, dir) => {
    setProjects((prev) => prev.map((p) => {
      if (p.id !== id) return p;
      const idx = PROJECT_STAGES.indexOf(p.status);
      const next = Math.min(PROJECT_STAGES.length - 1, Math.max(0, idx + dir));
      return { ...p, status: PROJECT_STAGES[next] };
    }));
  };
  const deleteProject = (id) => setProjects((prev) => prev.filter((p) => p.id !== id));
  const addProject = (p) => { setProjects((prev) => [...prev, p]); setAdding(false); };

  return (
    <div>
      <div className="flex items-center justify-between mb-5">
        <p className="text-xs" style={{ color: A.sub }}>Arrastra el avance con las flechas de cada tarjeta.</p>
        <button onClick={() => setAdding(true)} className="flex items-center gap-2 text-xs px-3.5 py-2.5 rounded-full font-semibold" style={{ background: A.ink, color: "#fff" }}>
          <Plus size={13} /> Nuevo proyecto
        </button>
      </div>
      <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {PROJECT_STAGES.map((stage) => {
          const items = projects.filter((p) => p.status === stage);
          return (
            <div key={stage} className="rounded-2xl p-3" style={{ background: A.bg, border: `1px solid ${A.line}` }}>
              <p className="text-xs font-semibold px-2 py-1.5 mb-2" style={{ color: A.ink }}>{stage} <span style={{ color: A.sub, fontWeight: 400 }}>({items.length})</span></p>
              <div className="flex flex-col gap-2">
                {items.map((p) => {
                  const idx = PROJECT_STAGES.indexOf(p.status);
                  return (
                    <div key={p.id} className="rounded-xl p-3" style={{ background: A.panel, border: `1px solid ${A.line}` }}>
                      <p className="text-xs font-semibold mb-1" style={{ color: A.ink }}>{p.title}</p>
                      <p className="text-[11px] mb-2" style={{ color: A.sub }}>{p.product} · {p.date}</p>
                      <div className="flex items-center justify-between">
                        <div className="flex gap-1">
                          <button disabled={idx === 0} onClick={() => moveProject(p.id, -1)} className="w-6 h-6 rounded flex items-center justify-center disabled:opacity-30" style={{ background: A.bg }}><ChevronLeft size={12} /></button>
                          <button disabled={idx === PROJECT_STAGES.length - 1} onClick={() => moveProject(p.id, 1)} className="w-6 h-6 rounded flex items-center justify-center disabled:opacity-30" style={{ background: A.bg }}><ChevronRight size={12} /></button>
                        </div>
                        <button onClick={() => setConfirmId(p.id)}><Trash2 size={12} style={{ color: A.sub }} /></button>
                      </div>
                    </div>
                  );
                })}
                {items.length === 0 && <p className="text-[11px] px-2" style={{ color: A.sub }}>Sin proyectos aquí.</p>}
              </div>
            </div>
          );
        })}
      </div>
      {adding && <NuevoProyectoForm onCancel={() => setAdding(false)} onSave={addProject} />}
      {confirmProject && (
        <ConfirmDialog
          title="¿Eliminar este proyecto?"
          message={`Se quitará "${confirmProject.title}" del tablero.`}
          onConfirm={() => { deleteProject(confirmId); setConfirmId(null); }}
          onCancel={() => setConfirmId(null)}
        />
      )}
    </div>
  );
}

function NuevoProyectoForm({ onCancel, onSave }) {
  const [f, setF] = useState({ title: "", client: "", product: "" });
  const submit = () => {
    if (!f.title) return;
    onSave({ id: "PRY-" + Math.floor(Math.random() * 900 + 100), title: f.title, client: f.client, product: f.product, status: "Cotización", date: new Date().toISOString().slice(0, 10) });
  };
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-5" style={{ background: "rgba(34,29,23,0.35)" }} onClick={onCancel}>
      <div className="w-full max-w-sm rounded-2xl p-6" style={{ background: A.panel }} onClick={(e) => e.stopPropagation()}>
        <p className="text-sm font-semibold mb-4" style={{ color: A.ink }}>Nuevo proyecto</p>
        <div className="flex flex-col gap-3 mb-5">
          <input value={f.title} onChange={(e) => setF((s) => ({ ...s, title: e.target.value }))} placeholder="Título del proyecto" className="ai2" />
          <input value={f.client} onChange={(e) => setF((s) => ({ ...s, client: e.target.value }))} placeholder="Cliente" className="ai2" />
          <input value={f.product} onChange={(e) => setF((s) => ({ ...s, product: e.target.value }))} placeholder="Producto" className="ai2" />
        </div>
        <div className="flex gap-2">
          <button onClick={submit} className="text-xs px-4 py-2.5 rounded-full font-semibold" style={{ background: A.ink, color: "#fff" }}>Crear</button>
          <button onClick={onCancel} className="text-xs px-4 py-2.5 rounded-full" style={{ color: A.sub }}>Cancelar</button>
        </div>
        <style>{`.ai2 { width:100%; border:1px solid ${A.line}; border-radius:8px; padding:9px 11px; font-size:13px; color:${A.ink}; background:${A.bg}; }`}</style>
      </div>
    </div>
  );
}

function StubView({ title, note }) {
  return (
    <div className="rounded-2xl p-10 text-center" style={{ background: A.panel, border: `1px dashed ${A.line}` }}>
      <p className="text-sm font-semibold mb-2" style={{ color: A.ink }}>{title}</p>
      <p className="text-xs max-w-sm mx-auto" style={{ color: A.sub }}>{note} — Sección preparada para la siguiente fase de producción.</p>
    </div>
  );
}
